//go:build chart

// The config subtree of the chart trove-bastion is the schema the binary emits for the role bastion
// (docs/spec/bastion.md R-BAS-046, R-BAS-002, Q-BAS-58; the mechanism of R-HA-029): values.schema.json holds it
// as generated by `go generate ./internal/config`, a typo under config fails at helm, and the keys the chart
// renders into /etc/trove/trove.yaml are in that schema and marked chart-managed.
package chart_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"testing"

	"go.yaml.in/yaml/v3"
)

func readJSONFile(t *testing.T, path string) map[string]any {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var v map[string]any
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("%s: %v", path, err)
	}
	return v
}

func roleSchema(t *testing.T) map[string]any {
	t.Helper()
	return readJSONFile(t, filepath.Join(repoRoot, "internal", "config", "bastion.schema.json"))
}

// schemaNode walks a rendered key path (array indices allowed) down the role schema. It returns the node, whether
// the path exists, and whether the node or one of its ancestors is marked x-trove-chart-managed.
func schemaNode(root map[string]any, path string) (node map[string]any, found, managed bool) {
	node = root
	for _, seg := range strings.Split(path, ".") {
		if _, err := strconv.Atoi(seg); err == nil {
			items, ok := node["items"].(map[string]any)
			if !ok {
				return nil, false, managed
			}
			node = items
			continue
		}
		props, _ := node["properties"].(map[string]any)
		child, ok := props[seg].(map[string]any)
		if !ok {
			return nil, false, managed
		}
		node = child
		if m, _ := node["x-trove-chart-managed"].(bool); m {
			managed = true
		}
	}
	return node, true, managed
}

// TestR_BAS_046_ConfigIsTheGeneratedRoleSchema (R-BAS-046, Q-BAS-58): the config property of values.schema.json is
// the committed role schema without $schema and $id, and chart-managed-keys.yaml lists exactly the managed
// subtrees of it. A drift means make generate was not run (make generate-check fails the same way in CI).
func TestR_BAS_046_ConfigIsTheGeneratedRoleSchema(t *testing.T) {
	role := roleSchema(t)
	delete(role, "$schema")
	delete(role, "$id")
	chartSchema := readJSONFile(t, filepath.Join(bastionDir(), "values.schema.json"))
	got := at(chartSchema, "properties", "config")
	if !reflect.DeepEqual(got, any(role)) {
		t.Fatal("properties.config of values.schema.json differs from internal/config/bastion.schema.json; run make generate")
	}
	if at(chartSchema, "properties", "config", "additionalProperties") != false {
		t.Error("config does not refuse unknown keys")
	}
	raw, err := os.ReadFile(filepath.Join(bastionDir(), "chart-managed-keys.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	var listed []string
	if err := yaml.Unmarshal(raw, &listed); err != nil {
		t.Fatal(err)
	}
	// Every x-trove-chart-managed leaf of the schema is under a listed path, and every listed path is managed.
	var leaves []string
	var walk func(n map[string]any, p string)
	walk = func(n map[string]any, p string) {
		if m, _ := n["x-trove-chart-managed"].(bool); m {
			leaves = append(leaves, p)
		}
		props, _ := n["properties"].(map[string]any)
		for k, c := range props {
			child := c.(map[string]any)
			if p != "" {
				walk(child, p+"."+k)
			} else {
				walk(child, k)
			}
		}
	}
	walk(role, "")
	for _, l := range leaves {
		var covered bool
		for _, p := range listed {
			if l == p || strings.HasPrefix(l, p+".") {
				covered = true
			}
		}
		if !covered {
			t.Errorf("chart-managed-keys.yaml does not list %s, which the role schema marks chart-managed", l)
		}
	}
	for _, p := range listed {
		node, found, _ := schemaNode(role, p)
		if !found {
			t.Errorf("chart-managed-keys.yaml lists %s, which is not in the role schema", p)
			continue
		}
		var managedBelow func(n map[string]any) bool
		managedBelow = func(n map[string]any) bool {
			if m, _ := n["x-trove-chart-managed"].(bool); m {
				return true
			}
			props, _ := n["properties"].(map[string]any)
			if len(props) == 0 {
				return false
			}
			for _, c := range props {
				if !managedBelow(c.(map[string]any)) {
					return false
				}
			}
			return true
		}
		if !managedBelow(node) {
			t.Errorf("chart-managed-keys.yaml lists %s, but the role schema leaves keys below it to the operator", p)
		}
	}
}

// TestR_BAS_046_ATypoUnderConfigFailsAtHelm (R-BAS-046): the schema refuses an unknown key, a wrong type and an
// out-of-range value under config on helm template and helm lint, and the error names the key.
func TestR_BAS_046_ATypoUnderConfigFailsAtHelm(t *testing.T) {
	cases := []struct {
		name string
		set  string
		want []string
	}{
		{"unknown key under bastion.answers", "config.bastion.answers.perod=5m", []string{"perod"}},
		{"unknown section", "config.bastian.answers.period=5m", []string{"bastian"}},
		{"unknown key under valkey", "config.valkey.sentinal.addresses={a:1}", []string{"sentinal"}},
		{"wrong type", "config.bastion.answers.max_entries=many", []string{"max_entries"}},
		{"below the minimum", "config.bastion.answers.max_entries=10", []string{"max_entries"}},
		{"an enum value outside", "config.valkey.tls.mode=sometimes", []string{"mode"}},
	}
	for _, c := range cases {
		t.Run(c.name+"/template", func(t *testing.T) {
			bstFails(t, bstRequired(), []string{c.set}, c.want...)
		})
		t.Run(c.name+"/lint", func(t *testing.T) {
			args := []string{"lint", "--strict", bastionDir(), "-f", bstRequired()[0], "--set", c.set}
			stdout, stderr, err := helm(t, args...)
			out := stdout + stderr
			if err == nil {
				t.Fatalf("helm lint succeeded, want a failure naming %q", c.want)
			}
			for _, w := range c.want {
				if !strings.Contains(out, w) {
					t.Errorf("lint error does not name %q:\n%s", w, out)
				}
			}
		})
	}
	t.Run("a valid key under config renders", func(t *testing.T) {
		_, docs := bstRender(t, bstRequired(), "config.bastion.answers.period=10m")
		if got := at(bstConfig(t, docs), "bastion", "answers", "period"); got != "10m" {
			t.Errorf("bastion.answers.period = %v", got)
		}
	})
}

// TestR_BAS_002_ChartManagedKeysAreRefusedUnderConfig (R-BAS-002, R-BAS-046): every path of
// chart-managed-keys.yaml is refused with a message naming the key, and so is a key below such a path.
func TestR_BAS_002_ChartManagedKeysAreRefusedUnderConfig(t *testing.T) {
	raw, err := os.ReadFile(filepath.Join(bastionDir(), "chart-managed-keys.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	var listed []string
	if err := yaml.Unmarshal(raw, &listed); err != nil {
		t.Fatal(err)
	}
	if len(listed) < 10 {
		t.Fatalf("chart-managed-keys.yaml lists %d paths", len(listed))
	}
	for _, p := range listed {
		t.Run(p, func(t *testing.T) {
			value := "x"
			if p == "bastion.replicas" {
				value = "9"
			}
			if node, _, _ := schemaNode(roleSchema(t), p); node["type"] == "object" {
				// A subtree: the schema rejects a string, so the test sets a scalar key inside it.
				var ok bool
				if p, value, ok = scalarBelow(node, p); !ok {
					t.Fatalf("no scalar key below %s", p)
				}
			}
			bstFails(t, bstRequired(), []string{"config." + p + "=" + value}, "config."+p, "managed by the chart")
		})
	}
	t.Run("a key inside a managed subtree", func(t *testing.T) {
		bstFails(t, bstRequired(), []string{"config.server.tls.min_version=1.3"}, "config.server.tls", "managed by the chart")
	})
	t.Run("the schema alone knows the key and the chart still refuses it", func(t *testing.T) {
		// bastion.main.token_file is in the role schema (the binary reads it), so the schema accepts it.
		bstFails(t, bstRequired(), []string{"config.bastion.main.token_file=/tmp/token"}, "config.bastion.main.token_file")
	})
	t.Run("the credential file of the workload identity is the operator's", func(t *testing.T) {
		_, docs := bstRender(t, []string{bastionSet("bucket-valkey")},
			"config.bastion.cache.bucket.credentials.source=webIdentity",
			"config.bastion.cache.bucket.credentials.web_identity_token_file=/var/run/secrets/eks.amazonaws.com/serviceaccount/token")
		if got := at(bstConfig(t, docs), "bastion", "cache", "bucket", "credentials", "web_identity_token_file"); got == nil {
			t.Error("web_identity_token_file was not rendered from the operator's value")
		}
	})
}

// TestR_BAS_046_EveryRenderedKeyIsInTheRoleSchemaAndManaged (R-BAS-046, R-BAS-002): in every value set of the
// chart, each key of /etc/trove/trove.yaml that the operator did not set is rendered by the chart, so it exists in
// the role schema and is marked chart-managed there; each key the operator set exists in the schema.
func TestR_BAS_046_EveryRenderedKeyIsInTheRoleSchemaAndManaged(t *testing.T) {
	role := roleSchema(t)
	defaults := userConfigLeaves(t, filepath.Join(bastionDir(), "values.yaml"))
	type variant struct {
		name  string
		files []string
		sets  []string
	}
	var variants []variant
	sets, err := filepath.Glob(filepath.Join(bastionDir(), "ci", "*.yaml"))
	if err != nil || len(sets) == 0 {
		t.Fatalf("no ci value sets: %v", err)
	}
	for _, f := range sets {
		variants = append(variants, variant{name: filepath.Base(f), files: []string{f}})
	}
	bv := bastionSet("bucket-valkey")
	variants = append(variants,
		variant{"bucket-valkey without a Valkey CA Secret", []string{bv}, []string{"secrets.valkeyCA.existingSecret="}},
		variant{"bucket-valkey with a Valkey user", []string{bv}, []string{"secrets.valkey.usernameKey=username"}},
		variant{"bucket-valkey with the workload identity", []string{bv}, []string{"config.bastion.cache.bucket.credentials.source=default"}},
		variant{"required-only without TLS", bstRequired(), []string{"tls.enabled=false"}},
	)
	for _, v := range variants {
		t.Run(v.name, func(t *testing.T) {
			_, docs := bstRender(t, v.files, v.sets...)
			rendered := map[string]bool{}
			var leaves []string
			leafPathsDeep("", bstConfig(t, docs), &leaves)
			for _, l := range leaves {
				rendered[l] = true
			}
			operator := map[string]bool{}
			for p := range defaults {
				operator[p] = true
			}
			for _, f := range v.files {
				for p := range userConfigLeaves(t, f) {
					operator[p] = true
				}
			}
			for _, s := range v.sets {
				if k, _, ok := strings.Cut(s, "="); ok && strings.HasPrefix(k, "config.") {
					operator[strings.TrimPrefix(k, "config.")] = true
				}
			}
			var chartKeys int
			for _, l := range leaves {
				_, found, managed := schemaNode(role, l)
				if !found {
					t.Errorf("%s is rendered into trove.yaml but is not in the role schema", l)
					continue
				}
				if !operator[l] && !operatorPrefix(operator, l) {
					chartKeys++
					if !managed {
						t.Errorf("%s is rendered by the chart but not marked x-trove-chart-managed in the role schema", l)
					}
				}
			}
			if chartKeys == 0 {
				t.Error("the chart rendered no key of its own")
			}
		})
	}
	t.Run("the keys of the Secret mounts are the managed file keys", func(t *testing.T) {
		_, docs := bstRender(t, []string{bv})
		cfg := bstConfig(t, docs)
		for _, p := range []string{
			"bastion.cache.bucket.credentials.access_key_id_file", "bastion.cache.bucket.credentials.secret_access_key_file",
			"valkey.password_file", "valkey.username_file", "valkey.tls.ca_file", "bastion.signing_key_file", "bastion.main.token_file",
		} {
			if _, found, managed := schemaNode(role, p); !found || !managed {
				t.Errorf("%s: in the role schema = %v, chart-managed = %v", p, found, managed)
			}
		}
		if at(cfg, "tracing", "ca_file") == nil {
			t.Error("tracing.ca_file is not rendered with tracing enabled and a trust bundle")
		}
	})
}

// operatorPrefix reports whether the operator set a map below or at a parent of the rendered leaf that is a
// non-map value (a list the operator wrote, for example trusted_proxies, whose indices the leaf carries).
func operatorPrefix(operator map[string]bool, leaf string) bool {
	segs := strings.Split(leaf, ".")
	for i := len(segs) - 1; i > 0; i-- {
		if _, err := strconv.Atoi(segs[i]); err != nil {
			continue
		}
		if operator[strings.Join(segs[:i], ".")] {
			return true
		}
	}
	return false
}

// userConfigLeaves returns the leaf paths of the config tree of a values file; a list is one leaf.
func userConfigLeaves(t *testing.T, path string) map[string]bool {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var vals map[string]any
	if err := yaml.Unmarshal(raw, &vals); err != nil {
		t.Fatal(err)
	}
	var leaves []string
	leafPaths("", vals["config"], &leaves)
	out := map[string]bool{}
	for _, l := range leaves {
		if l != "" {
			out[l] = true
		}
	}
	return out
}

// leafPathsDeep is leafPaths that descends into lists: a list item is a path segment of its index.
func leafPathsDeep(prefix string, v any, out *[]string) {
	switch x := v.(type) {
	case map[string]any:
		if len(x) == 0 {
			*out = append(*out, prefix)
			return
		}
		keys := make([]string, 0, len(x))
		for k := range x {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		for _, k := range keys {
			p := k
			if prefix != "" {
				p = prefix + "." + k
			}
			leafPathsDeep(p, x[k], out)
		}
	case []any:
		if len(x) == 0 {
			*out = append(*out, prefix)
			return
		}
		for i, c := range x {
			leafPathsDeep(prefix+"."+strconv.Itoa(i), c, out)
		}
	default:
		*out = append(*out, prefix)
	}
}

// scalarBelow is the path and a valid --set value of the first scalar key (alphabetically) below a node of the
// role schema; the schema checks types before the chart's own validation runs, so the value must fit.
func scalarBelow(node map[string]any, path string) (string, string, bool) {
	props, _ := node["properties"].(map[string]any)
	keys := make([]string, 0, len(props))
	for k := range props {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		child := props[k].(map[string]any)
		p := path + "." + k
		if _, nested := child["properties"]; nested {
			if sp, sv, ok := scalarBelow(child, p); ok {
				return sp, sv, true
			}
			continue
		}
		switch child["type"] {
		case "string":
			if enum, ok := child["enum"].([]any); ok {
				return p, enum[0].(string), true
			}
			if _, pat := child["pattern"]; !pat {
				return p, "x", true
			}
		case "boolean":
			return p, "true", true
		}
	}
	return "", "", false
}
